#include <iostream>
using namespace std;
int main() {
    float m1, m2, m3, m4, m5, m6, total, average, percentage;
    cout << "Enter marks of six subjects (out of 100 each): ";
    cin >> m1 >> m2 >> m3 >> m4 >> m5 >> m6;
    total = m1 + m2 + m3 + m4 + m5 + m6;
    average = total / 6;
    percentage = total / 600 * 100;
    cout << "Total = " << total << endl;
    cout << "Average = " << average << endl;
    cout << "Percentage = " << percentage << "%" << endl;
    return 0;
}

