#include <iostream>
#include <cmath>
using namespace std;
int main() {
    double a, b, c, d, r1, r2;
    cout << "Enter a, b and c of ax^2 + bx + c = 0: ";
    cin >> a >> b >> c;
    d = b * b - 4 * a * c;
    if (d > 0) {
        r1 = (-b + sqrt(d)) / (2 * a);
        r2 = (-b - sqrt(d)) / (2 * a);
        cout << "Real and different roots: " << r1 << " and " << r2 << endl;
    } else if (d == 0) {
        r1 = -b / (2 * a);
        cout << "Real and equal roots: " << r1 << endl;
    } else {
        double real = -b / (2 * a), imag = sqrt(-d) / (2 * a);
        cout << "Complex roots: " << real << " + " << imag << "i and " << real << " - " << imag << "i" << endl;
    }
    return 0;
}

